import { Component, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'app-filtro-tareas',
  imports: [FormsModule],
  template: `
    <input [(ngModel)]="texto" placeholder="Filtrar" />
    <label><input type="checkbox" [(ngModel)]="soloMias" /> Solo mías</label>
    <p>Buscando "{{ texto() }}"</p>
  `,
})
export class FiltroTareas {
  readonly texto = signal('');
  readonly soloMias = signal(false);
}

